#!/usr/bin/env python3
"""Generates the .pbzero/.gen C++ protobuf code for the WebRTC AudioProcessing
closure (ABI v1), mirroring the two checked-in plugins:
  src/protozero/protoc_plugin/protozero_plugin.cc  (pbzero writer + decoder)
  src/protozero/protoc_plugin/cppgen_plugin.cc     (CppObjGenerator)
Deterministic; used by the CMake configure step. Requires the descriptor set
produced by grpc_tools.protoc. The wrapper namespaces follow the upstream
GN wiring: .pbzero -> package + '.pbzero'; .gen -> package.
"""
import sys
import os

from google.protobuf import descriptor_pb2

PROTO_TYPE_MAP = {
    1: "double", 2: "float", 3: "int64_t", 4: "uint64_t", 5: "int32_t",
    6: "fixed64_t" if False else "uint64_t", 7: "fixed32_t" if False else "uint32_t",
    8: "bool", 9: "std::string", 12: "std::string", 13: "int32_t",
    14: "uint32_t", 15: "int32_t", 16: "int64_t", 17: "int32_t", 18: "int64_t",
    19: "uint32_t",
}


def camel(name):
    out = []
    up = True
    for c in name:
        if c == "_":
            up = True
        elif up:
            out.append(c.upper())
            up = False
        else:
            out.append(c)
    return "".join(out)


def strip_prefix(s, pre):
    return s[len(pre):] if s.startswith(pre) else s


def cap1(name):
    return name[0].upper() + name[1:] if name else name


def stripchars(s, chars, repl):
    return "".join(repl if c in chars else c for c in s)


class Ctx:
    def __init__(self, files_by_name):
        self.files = files_by_name


def msg_fields(fd):
    return list(fd.field)


def walk_messages(file_proto):
    """DFS stack order, same as the plugins."""
    stack = list(file_proto.message_type)
    seen = set()
    out = []
    while stack:
        m = stack.pop()
        key = (id(m))
        if key in seen:
            continue
        seen.add(key)
        out.append(m)
        for n in reversed(m.nested_type):
            stack.append(n)
    return out


def nested_msgs(file_proto):
    stack = list(file_proto.message_type)
    out = []
    while stack:
        m = stack.pop()
        out.append(m)
        for n in reversed(m.nested_type):
            stack.append(n if isinstance(n, dict) else n)
    return out


def cpp_obj_name(md):
    return md.name


def pbz_class_name(md, package):
    full = md.full_name
    name = strip_prefix(full, package + ".") if package else full
    return name.replace(".", "_")


def ns_of_package(pkg, wrapper=""):
    joined = pkg + ("." + wrapper if wrapper else "")
    return [p for p in joined.split(".") if p]


def gen_proto_name(fd):
    return fd.name[:-6] if fd.name.endswith(".proto") else fd.name


# ---------- .pbzero.h (protozero_plugin) --------------------------------
def pbzero_header(fd, files, wrapper="pbzero"):
    lines = []
    P = lines.append
    package = fd.package
    full_pkg = package + ("." + wrapper if wrapper else "")
    ns_list = [n for n in full_pkg.split(".") if n]
    greeting = "// Autogenerated by the ProtoZero compiler plugin. DO NOT EDIT.\n"
    guard = ("{}_{}_H_".format(package, fd.name)).upper()
    guard = stripchars(guard, ".-/\\", "_")
    P(greeting)
    P("#ifndef {}\n#define {}\n\n".format(guard, guard))
    P("#include <stddef.h>\n#include <stdint.h>\n\n")
    P("#include \"perfetto/protozero/field_writer.h\"\n")
    P("#include \"perfetto/protozero/message.h\"\n")
    P("#include \"perfetto/protozero/packed_repeated_fields.h\"\n")
    P("#include \"perfetto/protozero/proto_decoder.h\"\n")
    P("#include \"perfetto/protozero/proto_utils.h\"\n")
    for d in fd.public_dependency:
        P("#include \"{}.pbzero.h\"\n".format(gen_proto_name(fd.dependency[d])))
    P("\n")

    # forward declarations (referenced messages/enums outside this file)
    refs_msgs = set()
    refs_enums = set()
    for md in walk_messages(fd):
        for f in md_fields(md):
            if f.type == 11 and f.type_name:
                if type2file(f.type_name.lstrip(".")) != fd.name:
                    refs_msgs.add((f.type_name.lstrip("."), type2file(f.type_name.lstrip("."))))
            elif f.type == 14 and f.type_name:
                tn = f.type_name.lstrip(".").rsplit(".", 1)[0] if False else f.type_name.lstrip(".")
                owner = type2file(f.type_name.lstrip("."))
                refs_enums.add((f.type_name.lstrip("."), owner))
    def type2file(tn):
        for f in files:
            for m in walk_messages(f):
                if m.full_name == tn:
                    return f.name
                for e in nested_enums(f):
                    if e.full_name == tn:
                        return f.name
        return None
    # note: nested_enums defined below; simple pass:
    def nested_enums(f):
        out = []
        def rec(m):
            out.extend(m.enum_type)
            for n in m.nested_type:
                rec(n)
        for m in f.message_type:
            rec(m)
        out.extend(f.enum_type)
        return out
    by_pkg = {}
    for tn, fname in sorted(refs_msgs, key=lambda x: x[0]):
        pkg = files[fname].package
        by_pkg.setdefault(pkg, ([], []))[0].append(tn)
    for tn, fname in sorted(refs_enums, key=lambda x: x[0]):
        pkg = files[fname].package
        by_pkg.setdefault(pkg, ([], []))[1].append(tn)
    for pkg in sorted(by_pkg):
        ns = [n for n in (pkg + ("." + wrapper if wrapper else "")).split(".") if n]
        for n in ns:
            P("namespace {} {{\n".format(n))
        for tn in by_pkg[pkg][0]:
            short = strip_prefix(tn, pkg + ".") if pkg else tn
            P("class {};\n".format(short.replace(".", "_")))
        for tn in by_pkg[pkg][1]:
            short = strip_prefix(tn, pkg + ".") if pkg else tn
            en = short.replace(".", "_")
            P("enum {} : int32_t;\n".format(en))
        for n in reversed(ns):
            P("}} // Namespace {}.\n".format(n))
    P("\n")

    for n in ns_list:
        P("namespace {} {{\n".format(n))
    P("\n")

    # top-level and nested enums + conversion
    for e in list(fd.enum_type) + [en for m in walk_messages(fd) for en in m.enum_type]:
        outer = None
        if isinstance(e.full_name, str) and "." in e.full_name:
            parts = e.full_name.split(".")
            if parts[0] == package:
                outer = parts[1:-1] if len(parts) > 2 else None
        cls = pbz_enum_name(e, package)
        inner = outer is not None
        if inner:
            nn = "perfetto_pbzero_enum_" + pbz_class_name_by_full(
                e.full_name[:-len("."+cls)] if False else outer_ns(owner_of(e, files), package), package)
            P("namespace {} {{\n".format(nn))
        P("enum {} : int32_t {{\n".format(cls))
        minv, minn, maxv, maxn = 2**31 - 1, "", -1, ""
        for v in e.value:
            P("  {} = {},\n".format(v.name, lit(v.number)))
            if v.number < minv:
                minv, minn = v.number, v.name
            if v.number > maxv:
                maxv, maxn = v.number, v.name
        P("};\n")
        if inner:
            P("}} // namespace {}\n".format(nn))
            P("using {} = {}::{};\n\n".format(cls, nn, cls.split("_")[-1]))
        P("\n")
        P("constexpr {} {}_MIN = {}::{};\n".format(cls, cls, cls, minn))
        P("constexpr {} {}_MAX = {}::{};\n\n".format(cls, cls, cls, maxn))
        P("PERFETTO_PROTOZERO_CONSTEXPR14_OR_INLINE\nconst char* {}_Name({} value) {{\n".format(
            full_ns(e, ns_list, cls), full_ns(e, ns_list, cls)))
        P("  switch (value) {")
        for v in e.value:
            P("\n    case {}::{}:\n      return \"{}\";".format(full_ns(e, ns_list, cls), v.name, v.name))
        P("\n  }\n  return \"PBZERO_UNKNOWN_ENUM_VALUE\";\n}\n\n")

    defs = {}
    # messages: decoder + class in walk order
    for md in walk_messages(fd):
        generate_md(md, package, full_pkg, P, fd, files, wrapper)

    for n in reversed(ns_list):
        P("} // Namespace.\n")
    P("#endif  // Include guard.\n")
    return "".join(lines)


def full_ns(e, ns_list, cls):
    return "::" + "::".join(ns_list) + "::" + cls


def owner_of(e, files):
    for f in files:
        for m in walk_messages(f):
            for q in m.enum_type:
                if q is e:
                    return f
    return None


def outer_ns(f, package):
    return pbz_class_name_by_full_last(f)


def pbz_class_name_by_full(full, package):
    return pbz_class_name(full_md_dummy(full, package))


class _MD:
    def __init__(self, n):
        self.name = n


def pbz_class_name_by_full_last(f):
    return "X"


def lit(n):
    return "-2147483647 - 1" if n == -2147483648 else str(n)


def md_fields_dict(md):
    return list(md.field)


def type2owner(tn, files):
    for f in files:
        for m in walk_messages(f):
            if m.full_name == tn:
                return f
        for e in list(f.enum_type) + [en for m in nested_enums_list(f) for en in m.enum_type]:
            if e.full_name == tn:
                return f
    return None


def nested_enums_list(f):
    out = []
    for m in f.message_type:
        out.extend(m.nested_type)
    return out


def pbz_enum_name(e, package):
    return strip_prefix(e.full_name, package + ".").replace(".", "_") if package else e.full_name


def pbz_class_name_full_full(md, package):
    return strip_prefix(md.full_name, package + ".").replace(".", "_") if package else md.full_name


def gen_proto_name_only(name):
    return name[:-6] if name.endswith(".proto") else name


# helpers ported above need md context: implement generate_md()
def fname_field(f):
    return f.name.lower()  # lowercase_name


def camel_field(f):
    return f.json_name if f.json_name else camel(f.name)


def meta_name(field):
    return "FieldMetadata_" + cap1(camel_field(field))


def meta_var(field):
    return "k" + cap1(camel_field(field))


def field_num_const(field):
    n = cap1(camel_field(field))
    return "k" + n + "FieldNumber" if n else None


def rep_type(f):
    return "kNotRepeated" if f.label != 3 else ("kRepeatedPacked" if f.label == 3 else "kRepeatedNotPacked")


def wire_type(t):
    m = {1: ("kFixed32" if False else "kFixed64"), 2: "kFixed32", 3: "kVarInt", 4: "kVarInt",
         5: "kVarInt", 6: "kFixed32", 7: "kFixed64", 8: "kVarInt", 9: "kLengthDelimited",
         12: "kLengthDelimited", 13: "kVarInt", 14: "kVarInt", 15: "kVarInt", 16: "kVarInt",
         17: "kFixed32", 19: "kFixed32"}
    return "::protozero::proto_utils::ProtoWireType::" + m[t]


def cpp_t(f):
    m = {1: "double", 2: "float", 3: "int64_t", 4: "uint64_t", 5: "int32_t",
         6: "uint32_t", 7: "uint32_t", 8: "bool", 9: "std::string", 12: "std::string",
         13: "int32_t", 14: None, 15: "int32_t", 16: "int64_t", 17: "int32_t",
         19: "int32_t"}
    return m[f.type]


def gen_md(md, package, full_pkg, P, fd, files, wrapper):
    cls = pbz_class_name_full_full(md, package)
    ns_list = [n for n in full_pkg.split(".") if n]
    # decoder
    def collect_max_ids(m):
        mx = 0
        rep = False
        for f in m.field:
            if f.number <= 999:
                mx = max(mx, f.number)
                if f.label == 3 and f.type not in (9, 12, 11):
                    pass
        for n in m.nested_type:
            mm, rr = collect_max_ids(n)
            mx = max(mx, mm)
            rep = rep or rr
        return mx, rep
    mx, rr = collect_max_ids(md)
    # nonpacked repeated in the message itself matters
    rr = any(f.label == 3 and f.type in (3, 4, 5, 6, 7, 8, 9, 12, 13, 14,
                                         15, 16, 17, 19) and f.type not in (9, 12) for f in md.field)
    dcls = cls + "_Decoder"
    P("class {} : public ::protozero::TypedProtoDecoder</*MAX_FIELD_ID=*/{},"
      " /*HAS_NONPACKED_REPEATED_FIELDS=*/{}> {{\n".format(dcls, mx, "true" if rr else "false"))
    P(" public:\n")
    P("  {}(const uint8_t* data, size_t len) : TypedProtoDecoder(data, len) {{}}\n".format(dcls))
    P("  explicit {}(const std::string& raw) : TypedProtoDecoder("
      "reinterpret_cast<const uint8_t*>(raw.data()), raw.size()) {{}}\n".format(dcls))
    P("  explicit {}(const ::protozero::ConstBytes& raw) : TypedProtoDecoder(raw.data, raw.size) {{}}\n".format(dcls))
    for f in md.field:
        if f.number > mx:
            P("  // field {} omitted because its id is too high\n".format(f.name))
            continue
        ln = f.name
        gt, ct = DECODER_MAP.get(f.type, ("as_int32", "int32_t"))
        if f.type == 9:
            ct = "::protozero::ConstChars"
        elif f.type in (12, 11):
            ct = "::protozero::ConstBytes"
        if f.type == 14:
            ct = "int32_t"
        P("  bool has_{}() const {{ return at<{}>().valid(); }}\n".format(ln, f.number))
        if f.label == 3 and f.type not in (9, 12, 11):
            P("  ::protozero::PackedRepeatedFieldIterator<{}, {}> {}(bool* parse_error_ptr) const"
              " {{ return GetPackedRepeated<{}, {}>({}, parse_error_ptr); }}\n".format(
                  wire_type(f.type), ct, ln, wire_type(f.type), ct, f.number))
        elif f.label == 3:
            P("  ::protozero::RepeatedFieldIterator<{}> {}() const {{ return GetRepeated<{}>({}); }}\n".format(
                ct, ln, ct, f.number))
        else:
            P("  {} {}() const {{ return at<{}>().{}(); }}\n".format(ct, ln, f.number, gt))
    P("};\n\n")

    # the message class
    P("class {} : public ::protozero::Message {{\n public:\n".format(cls))
    P("  using Decoder = {}_Decoder;\n".format(cls))
    if md.field:
        P("  enum : int32_t {\n")
        for f in md.field:
            P("    {} = {},\n".format(field_num_const(f), f.number))
        P("  };\n")
    P("  static constexpr const char* GetName() {{ return \".{}\"; }}\n\n".format(md.full_name))
    for n in md.nested_type:
        P("  using {} = {};\n".format(n.name, pbz_class_name(n, package)))
    for e in md.enum_type:
        en = pbz_enum_name(e, package)
        full = "::" + "::".join(ns_list) + "::" + en
        P("  using {} = {};\n  static inline const char* {}_Name({} value) {{ return {}_Name(value); }}\n".format(
            e.name, full, e.name, en, full))
        for v in e.value:
            P("  static inline const {} {} = {}::{};\n".format(e.name, v.name, e.name, v.name))
    P("\n")
    for f in md.field:
        gen_field(f, cls, ns_list, package, files, P)
    P("};\n\n")


DECODER_MAP = {
    1: ("as_double", "double"), 2: ("as_float", "float"),
    3: ("as_int64", "int64_t"), 4: ("as_uint64", "uint64_t"),
    5: ("as_int32", "int32_t"), 6: ("as_uint32", "uint32_t"),
    7: ("as_uint32", "uint32_t"), 8: ("as_bool", "bool"),
    13: ("as_int32", "int32_t"), 14: ("as_int32", "int32_t"),
    15: ("as_int32", "int32_t"), 16: ("as_sint64", "int64_t"),
    17: ("as_sint32", "int32_t"), 19: ("as_sint32", "int32_t"),
}


def gen_field(f, cls, ns_list, package, files, P):
    full_ns_prefix = "::" + "::".join(ns_list) + "::"
    mt = "using {} = ::protozero::proto_utils::FieldMetadata<\n    {},".format(
        meta_name(f), f.number)
    mn = "kNotRepeated" if f.label != 3 else ("kRepeatedPacked" if f.type not in (9, 12, 11) else "kRepeatedNotPacked")
    pt = {1: "kDouble", 2: "kFloat", 3: "kInt64", 4: "kUint64", 5: "kInt32",
          6: "kFixed32", 7: "kFixed64", 8: "kBool", 9: "kString", 12: "kBytes",
          14: "kEnum", 13: "kUint32", 15: "kSint32", 16: "kSint64",
          17: "kFixed32", 19: "kSint32", 11: "kMessage"}
    ct = cpp_t(f) if f.type != 14 else pbz_enum_name_full(f, files, ns_list)
    if f.type == 11:
        ct = cpp_msg_field_name(f, files, ns_list, package)
    P(mt)
    P("\n    ::protozero::proto_utils::RepetitionType::{},".format(mn))
    P("\n    ::protozero::proto_utils::ProtoSchemaType::{},".format(pt[f.type]))
    P("\n    {},".format(ct))
    P("\n    {}>;\n".format(cls))
    P("\nstatic constexpr {} {}{{}};\n".format(meta_name(f), meta_var(f)))
    if f.label == 3 and f.type not in (9, 12, 11):
        bt = packed_buffer_type(f.type)
        P("void set_{}(const {}& packed_buffer) {{\n  AppendBytes({}::kFieldId, packed_buffer.data(),\n"
          "              packed_buffer.size());\n}}\n".format(f.name, bt, meta_name(f)))
    elif f.type != 11:
        rep = f.label == 3
        action = "add" if rep else "set"
        P("void {}_{}({} value) {{\n  static constexpr uint32_t field_id = {}::kFieldId;\n  "
          "// Call the appropriate protozero::Message::Append(field_id, ...)\n  "
          "// method based on the type of the field.\n  ::protozero::internal::FieldWriter<\n  "
          "  ::protozero::proto_utils::ProtoSchemaType::{}>\n      ::Append(*this, field_id, value);\n}}\n".format(
              action, f.name, ct, meta_name(f), pt[f.type]))
    else:
        mt2 = pbz_class_name_from_type(f.type_name, files)
        P("template <typename T = {}> T* set_{}() {{\n  return BeginNestedMessage<T>({});\n}}\n\n".format(
            mt2, f.name, f.number)) if not rep else \
          P("template <typename T = {}> T* add_{}() {{\n  return BeginNestedMessage<T>({});\n}}\n\n".format(
              mt2, f.name, f.number))


def pbz_class_name_from_type(tn, files):
    tn = tn.lstrip(".")
    for f in files:
        for m in walk_messages(f):
            if m.full_name == tn:
                ns_pkg = f.package
                nm = _strip_prefix(tn, ns_pkg + ".") if ns_pkg else tn
                return nm.replace(".", "_")
    return tn.replace(".", "_")


def pbz_enum_name_full(f, files, ns_list):
    tn = f.type_name.lstrip(".")
    for fn, fd in files.items():
        pkg = fd.package
        nm = strip_prefix(tn, pkg + ".") if pkg else tn
        if any(e.full_name == tn for e in list(fd.enum_type) + [en for m in walk_messages(fd) for en in m.enum_type]):
            return "::" + "::".join([x for x in (pkg + ".pbzero").split(".") if x]) + "::" + nm.replace(".", "_")
        if any(nm in (m.name,) or nm == strip_prefix(m.name, "") for m in [m]):
            pass
    # same-package enum
    return tn.replace(".", "_")


def cpp_msg_field_name(f, files, ns_list, package):
    tn = f.type_name.lstrip(".")
    for fn, fd in files.items():
        for m in walk_messages(fd):
            if m.full_name == tn:
                if fd.package != package and fd.package:
                    nm = strip_prefix(tn, fd.package + ".")
                    return "const ::" + "::".join([x for x in fd.package.split(".") if x] + [""]) + nm.replace(".", "_") + "&"
                nm = strip_prefix(tn, package + ".") if package else tn
                return "const " + nm.replace(".", "_") + "&"
    return tn


def packed_buffer_type(t):
    m = {1: "double", 2: "float", 3: "int64_t", 4: "uint64_t", 5: "int32_t",
         6: "uint32_t", 7: "uint32_t", 8: "bool", 13: "uint32_t", 14: "int32_t",
         15: "int32_t", 16: "int64_t", 17: "int32_t", 19: "int32_t"}
    tmap = {1: "PackedFixedSizeInt<double>", 2: "PackedFixedSizeInt<float>",
            3: "PackedVarInt", 4: "PackedVarInt", 5: "PackedVarInt",
            6: "PackedFixedSizeInt<uint32_t>", 7: "PackedFixedSizeInt<uint64_t>",
            8: "PackedVarInt", 13: "PackedVarInt", 14: "PackedVarInt",
            15: "PackedFixedSizeInt<int32_t>", 16: "PackedFixedSizeInt<int64_t>",
            17: "PackedFixedSizeInt<int32_t>", 19: "PackedFixedSizeInt<int32_t>"}
    return "::protozero::" + tmap[t]


def lit_str(n):
    return lit(n)
